// Existing, working helper. Preserve its exported behavior.
export function normalizeSegments(input){
  if(typeof input!=='string')throw Error('invalid path');
  const segments=[];
  for(const part of input.split('/')){
    if(part===''||part==='.')continue;
    if(part==='..'){segments.pop();continue;}
    segments.push(part);
  }
  return segments;
}

function validatePath(value,label){
  if(typeof value!=='string'||value.length===0||value.includes('\0')){
    throw Error(`invalid ${label}`);
  }
}

function toAbsolutePath(segments){
  if(segments.length===0)return'/';
  return`/${segments.join('/')}`;
}

export function resolveWithin(root,candidate){
  validatePath(root,'root');
  validatePath(candidate,'candidate');
  if(!root.startsWith('/'))throw Error('invalid root');
  const rootSegments=normalizeSegments(root);
  const baseSegments=candidate.startsWith('/')?[]:rootSegments.slice();
  const resolvedSegments=normalizeSegments(baseSegments.join('/').concat(candidate));
  const resolved=toAbsolutePath(resolvedSegments);
  const inside=rootSegments.length<=resolvedSegments.length&&
    rootSegments.every((segment,index)=>segment===resolvedSegments[index]);
  let relative=null;
  if(inside){
    relative=resolvedSegments.slice(rootSegments.length).join('/');
  }
  return{inside,resolved,relative};
}

const isCli=import.meta.url===`file://${process.argv[1]}`;
if(isCli){
  const args=process.argv.slice(2);
  if(args.length!==1){
    process.stderr.write('usage: node path-scope.js INPUT_JSON_FILE\n');
    process.exit(2);
  }
  let raw;
  try{
    raw=await import('node:fs').then(fs=>fs.readFileSync(args[0],'utf8'));
  }catch{
    process.stderr.write('cannot read input file\n');
    process.exit(2);
  }
  let parsed;
  try{
    parsed=JSON.parse(raw);
  }catch{
    process.stderr.write('invalid JSON input\n');
    process.exit(2);
  }
  if(parsed===null||Array.isArray(parsed)||typeof parsed!=='object'){
    process.stderr.write('input must be a non-null, non-array object\n');
    process.exit(2);
  }
  try{
    const result=resolveWithin(parsed.root,parsed.candidate);
    process.stdout.write(`${JSON.stringify(result)}\n`);
    process.exit(0);
  }catch{
    process.stderr.write('invalid path input\n');
    process.exit(2);
  }
}

