import test from 'node:test';
import assert from 'node:assert/strict';
import {resolveWithin, normalizeSegments} from '../path-scope.js';
import {execFileSync, spawnSync} from 'node:child_process';
import {writeFileSync, unlinkSync, mkdtempSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';

// --- API edge cases ---

test('task example: relative candidate inside root', () => {
  assert.deepEqual(resolveWithin('/srv/ws', '../ws/sub/../file.txt'),
    {inside: true, resolved: '/srv/ws/file.txt', relative: 'file.txt'});
});

test('task example: absolute candidate outside root', () => {
  assert.deepEqual(resolveWithin('/srv/ws', '/srv/wsx'),
    {inside: false, resolved: '/srv/wsx', relative: null});
});

test('same location gives empty relative', () => {
  assert.deepEqual(resolveWithin('/a/b', '/a/b'),
    {inside: true, resolved: '/a/b', relative: ''});
});

test('root /a/b candidate /a/bc is outside (textual prefix not enough)', () => {
  assert.deepEqual(resolveWithin('/a/b', '/a/bc'),
    {inside: false, resolved: '/a/bc', relative: null});
});

test('candidate climbing above root is outside', () => {
  assert.deepEqual(resolveWithin('/a/b', '../c'),
    {inside: false, resolved: '/a/c', relative: null});
});

test('candidate climbing above filesystem root stays at /', () => {
  assert.deepEqual(resolveWithin('/a', '../../../../x'),
    {inside: false, resolved: '/x', relative: null});
});

test('backslash is an ordinary character', () => {
  assert.deepEqual(resolveWithin('/a', 'b\\c'),
    {inside: true, resolved: '/a/b\\c', relative: 'b\\c'});
});

test('segments like ..foo, ..., .hidden are ordinary names', () => {
  assert.deepEqual(resolveWithin('/a', '..foo/.../.hidden'),
    {inside: true, resolved: '/a/..foo/.../.hidden', relative: '..foo/.../.hidden'});
});

test('root / with candidate /x', () => {
  assert.deepEqual(resolveWithin('/', '/x'),
    {inside: true, resolved: '/x', relative: 'x'});
});

test('root / with candidate /', () => {
  assert.deepEqual(resolveWithin('/', '/'),
    {inside: true, resolved: '/', relative: ''});
});

test('root / with candidate x/../y', () => {
  assert.deepEqual(resolveWithin('/', 'x/../y'),
    {inside: true, resolved: '/y', relative: 'y'});
});

test('trailing slash in root is normalized away', () => {
  assert.deepEqual(resolveWithin('/a/b/', 'c'),
    {inside: true, resolved: '/a/b/c', relative: 'c'});
});

test('candidate with leading slash resolves from filesystem root', () => {
  assert.deepEqual(resolveWithin('/a/b', '/c/d'),
    {inside: false, resolved: '/c/d', relative: null});
});

test('candidate with leading slash inside root', () => {
  assert.deepEqual(resolveWithin('/a/b', '/a/b/c'),
    {inside: true, resolved: '/a/b/c', relative: 'c'});
});

test('invalid: empty root throws', () => {
  assert.throws(() => resolveWithin('', 'x'), Error);
});

test('invalid: empty candidate throws', () => {
  assert.throws(() => resolveWithin('/a', ''), Error);
});

test('invalid: NUL in root throws', () => {
  assert.throws(() => resolveWithin('/a\0b', 'x'), Error);
});

test('invalid: NUL in candidate throws', () => {
  assert.throws(() => resolveWithin('/a', 'x\0y'), Error);
});

test('invalid: root not starting with / throws', () => {
  assert.throws(() => resolveWithin('a/b', 'x'), Error);
});

test('invalid: non-string root throws', () => {
  assert.throws(() => resolveWithin(null, 'x'), Error);
});

test('invalid: non-string candidate throws', () => {
  assert.throws(() => resolveWithin('/a', null), Error);
});

test('inputs are not mutated', () => {
  const root = '/a/b';
  const candidate = 'c/d';
  resolveWithin(root, candidate);
  assert.equal(root, '/a/b');
  assert.equal(candidate, 'c/d');
});

// --- CLI tests ---

function runCli(args) {
  return spawnSync(process.execPath, ['path-scope.js', ...args], {encoding: 'utf8'});
}

test('CLI: valid input prints JSON and exits 0', () => {
  const dir = mkdtempSync(join(tmpdir(), 'ps-'));
  const file = join(dir, 'in.json');
  writeFileSync(file, JSON.stringify({root: '/srv/ws', candidate: 'file.txt'}));
  try {
    const r = runCli([file]);
    assert.equal(r.status, 0);
    assert.equal(r.stderr, '');
    const parsed = JSON.parse(r.stdout);
    assert.deepEqual(parsed, {inside: true, resolved: '/srv/ws/file.txt', relative: 'file.txt'});
    assert.ok(r.stdout.endsWith('\n'));
  } finally {
    unlinkSync(file);
  }
});

test('CLI: no args exits 2 with stderr', () => {
  const r = runCli([]);
  assert.equal(r.status, 2);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
});

test('CLI: two args exits 2 with stderr', () => {
  const r = runCli(['a', 'b']);
  assert.equal(r.status, 2);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
});

test('CLI: nonexistent file exits 2 with stderr', () => {
  const r = runCli(['/nonexistent/path/file.json']);
  assert.equal(r.status, 2);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
});

test('CLI: invalid JSON exits 2 with stderr', () => {
  const dir = mkdtempSync(join(tmpdir(), 'ps-'));
  const file = join(dir, 'bad.json');
  writeFileSync(file, 'not json');
  try {
    const r = runCli([file]);
    assert.equal(r.status, 2);
    assert.ok(r.stderr.length > 0);
    assert.equal(r.stdout, '');
  } finally {
    unlinkSync(file);
  }
});

test('CLI: JSON array exits 2 with stderr', () => {
  const dir = mkdtempSync(join(tmpdir(), 'ps-'));
  const file = join(dir, 'arr.json');
  writeFileSync(file, '[1,2]');
  try {
    const r = runCli([file]);
    assert.equal(r.status, 2);
    assert.ok(r.stderr.length > 0);
    assert.equal(r.stdout, '');
  } finally {
    unlinkSync(file);
  }
});

test('CLI: JSON null exits 2 with stderr', () => {
  const dir = mkdtempSync(join(tmpdir(), 'ps-'));
  const file = join(dir, 'null.json');
  writeFileSync(file, 'null');
  try {
    const r = runCli([file]);
    assert.equal(r.status, 2);
    assert.ok(r.stderr.length > 0);
    assert.equal(r.stdout, '');
  } finally {
    unlinkSync(file);
  }
});

test('CLI: invalid API input (empty root) exits 2 with stderr', () => {
  const dir = mkdtempSync(join(tmpdir(), 'ps-'));
  const file = join(dir, 'inv.json');
  writeFileSync(file, JSON.stringify({root: '', candidate: 'x'}));
  try {
    const r = runCli([file]);
    assert.equal(r.status, 2);
    assert.ok(r.stderr.length > 0);
    assert.equal(r.stdout, '');
  } finally {
    unlinkSync(file);
  }
});

test('CLI: extra fields are ignored', () => {
  const dir = mkdtempSync(join(tmpdir(), 'ps-'));
  const file = join(dir, 'extra.json');
  writeFileSync(file, JSON.stringify({root: '/a', candidate: 'b', extra: 42}));
  try {
    const r = runCli([file]);
    assert.equal(r.status, 0);
    const parsed = JSON.parse(r.stdout);
    assert.deepEqual(parsed, {inside: true, resolved: '/a/b', relative: 'b'});
  } finally {
    unlinkSync(file);
  }
});

test('importing module does not run CLI', () => {
  // If the CLI ran on import, process.argv[1] would be the test runner,
  // and it would try to read a file. The fact that we got here without
  // a crash or exit means the CLI did not run.
  assert.ok(true);
});

